const MEM = window.MISSING_GROUPS_MEM;

// =========================================================
// НОВАЯ ФУНКЦИЯ РАСЧЕТА СТАВКИ ДЛЯ КАСКАДНОЙ СТРАТЕГИИ
// =========================================================
function calculateCustomGroupBet(progressionLevel, recoveryMode = false) {
    const flatSteps = MEM.config.customGroupFlatSteps || 9;
    const progSteps = MEM.config.customGroupProgressionSteps || 5;
    const baseMin = 0.00000018;
    const baseProg = MEM.config.customGroupProgressionBase || 0.1;

    if (recoveryMode) {
        return baseMin;
    }

    if (progressionLevel < flatSteps) {
        return baseMin;
    }

    let level = progressionLevel - flatSteps;
    if (level < progSteps) {
        return baseProg * Math.pow(2, level);
    }

    return baseMin;
}

// =========================================================
// ФУНКЦИИ ДЛЯ РАСЧЕТА СТАВОК (ОСТАЛЬНЫЕ)
// =========================================================
function calculateEvenChanceBet(progressionLevel = 0) {
    try {
        let baseBet = MEM.config.evenChanceBaseBet || 0.001;
        
        if (baseBet > 1 || baseBet < 0.0000001) {
            baseBet = 0.001;
            MEM.config.evenChanceBaseBet = 0.001;
        }
        
        if (!MEM.config.evenChanceProgression) {
            return Math.max(MEM.config.minBet, Math.min(MEM.config.maxBet, baseBet));
        }
        
        let betAmount = baseBet * Math.pow(MEM.config.evenChanceMultiplier || 2, progressionLevel);
        
        if (progressionLevel >= (MEM.config.evenChanceMaxLevel || 8)) {
            betAmount = baseBet * Math.pow(MEM.config.evenChanceMultiplier || 2, MEM.config.evenChanceMaxLevel || 8);
        }
        
        return Number(Math.max(MEM.config.minBet || 0.00001, 
                      Math.min(MEM.config.maxBet || 0.5, betAmount))
                      .toFixed(8));
    } catch (error) {
        return 0.001;
    }
}

function updateProgressionAfterLoss(betType, progressionData) {
    progressionData.progressionLevel++;
    return progressionData;
}

function updateProgressionAfterWin(betType, progressionData) {
    return { progressionLevel: 0 };
}

// =========================================================
// ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// =========================================================

function getNumberColor(number) {
    if (number === 0) return 'green';
    const reds = [1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];
    return reds.includes(number) ? 'red' : 'black';
}

function getGroupsForNumber(number) {
    const groups = [];
    for (const [groupName, groupData] of Object.entries(MEM.allGroups)) {
        if (groupData.numbers.includes(number)) {
            groups.push(groupName);
        }
    }
    return groups;
}

function updateMissCounters(number) {
    for (const groupName in MEM.currentMisses) {
        MEM.currentMisses[groupName]++;
    }
    
    const hitGroups = getGroupsForNumber(number);
    hitGroups.forEach(groupName => {
        if (MEM.currentMisses[groupName] > MEM.maxMisses[groupName]) {
            MEM.maxMisses[groupName] = MEM.currentMisses[groupName];
        }
        MEM.currentMisses[groupName] = 0;
    });
    
    return hitGroups;
}

function checkGroupForBet(groupName) {
    const groupType = MEM.allGroups[groupName].type;
    const currentMiss = MEM.currentMisses[groupName];
    
    if (!MEM.config.enabledBets[groupType]) return false;
    
    if (groupType === 'evenChance' && currentMiss >= MEM.config.evenChanceEntry) {
        return {
            group: groupName,
            type: groupType,
            currentMiss: currentMiss,
            maxSpins: MEM.config.evenChanceMaxSpins
        };
    }
    
    if (groupType === 'customGroup' && currentMiss >= MEM.config.customGroupEntry) {
        return {
            group: groupName,
            type: groupType,
            currentMiss: currentMiss,
            maxSpins: MEM.config.customGroupMaxSpins
        };
    }
    
    return false;
}

function updateDrawdownTracking(profitChange) {
    const currentProfit = MEM.totalProfit || 0;
    
    if (currentProfit > MEM.profitPeak) {
        MEM.profitPeak = currentProfit;
    }
    
    const currentDrawdown = MEM.profitPeak - currentProfit;
    MEM.drawdownStats.currentDrawdown = currentDrawdown;
    
    if (currentDrawdown > MEM.drawdownStats.maxDrawdown) {
        MEM.drawdownStats.maxDrawdown = currentDrawdown;
    }
    
    if (MEM.totalSpins % 10 === 0) {
        MEM.drawdownStats.profitHistory.push({
            spin: MEM.totalSpins,
            profit: currentProfit,
            drawdown: currentDrawdown
        });
        if (MEM.drawdownStats.profitHistory.length > 100) {
            MEM.drawdownStats.profitHistory.shift();
        }
    }
}

// =========================================================
// ОБРАБОТКА ВЫИГРЫША
// =========================================================
function processWin(betIndex, winningNumber) {
    try {
        const bet = MEM.activeBets[betIndex];
        if (!bet) return;
        
        const winAmount = bet.betAmount || 0;
        const netProfit = winAmount;
        const step = bet.progressionLevel + 1;
        
        MEM.totalWins = (MEM.totalWins || 0) + 1;
        MEM.totalProfit = (MEM.totalProfit || 0) + netProfit;
        
        if (!MEM.statsByType[bet.type]) {
            MEM.statsByType[bet.type] = { wins:0, profit:0, amountBet:0, winSteps:{}, currentLosingStreak:0 };
        }
        
        MEM.statsByType[bet.type].wins = (MEM.statsByType[bet.type].wins || 0) + 1;
        MEM.statsByType[bet.type].profit = (MEM.statsByType[bet.type].profit || 0) + netProfit;
        MEM.statsByType[bet.type].amountBet = (MEM.statsByType[bet.type].amountBet || 0) + bet.betAmount;
        
        let stepKey = bet.recoveryMode ? `R${step}` : `${step}`;
        MEM.statsByType[bet.type].winSteps[stepKey] = (MEM.statsByType[bet.type].winSteps[stepKey] || 0) + 1;
        
        if (bet.type === 'customGroup') {
            if (!MEM.statsByType.customGroup.progressionStats) {
                MEM.statsByType.customGroup.progressionStats = {
                    maxLevel: 0,
                    totalProgressions: 0,
                    levels: {},
                    lastLevels: []
                };
            }
            
            const stats = MEM.statsByType.customGroup.progressionStats;
            const level = step;
            
            if (level > stats.maxLevel) stats.maxLevel = level;
            stats.totalProgressions++;
            stats.levels[level] = (stats.levels[level] || 0) + 1;
            stats.lastLevels.push(level);
            if (stats.lastLevels.length > 10) stats.lastLevels.shift();
        }
        
        MEM.statsByType[bet.type].currentLosingStreak = 0;
        MEM.drawdownStats.currentLosingSpins = 0;
        
        MEM.balance = (MEM.balance || 100) + netProfit;
        
        if (!MEM.detailedHistory) MEM.detailedHistory = [];
        MEM.detailedHistory.push({
            spin: MEM.totalSpins,
            type: 'WIN',
            group: bet.group,
            step: step,
            recovery: bet.recoveryMode || false,
            amount: bet.betAmount,
            profit: netProfit,
            totalProfit: MEM.totalProfit
        });
        if (MEM.detailedHistory.length > 100) MEM.detailedHistory.shift();
        
        if (MEM.config.diagnostics.logLevel === 'detailed') {
            console.log(`  ✅ WIN ${bet.group} | ШАГ ${step}${bet.recoveryMode ? ' (R)' : ''} | +${netProfit.toFixed(6)} | Баланс: ${(MEM.balance || 0).toFixed(2)}`);
        }
        
        MEM.activeBets.splice(betIndex, 1);
        updateDrawdownTracking(netProfit);
    } catch (error) {
        console.error("Ошибка в processWin:", error);
    }
}

// =========================================================
// ОБРАБОТКА ПРОИГРЫША
// =========================================================
function processLoss(betIndex) {
    try {
        const bet = MEM.activeBets[betIndex];
        if (!bet) return;
        
        bet.spinsCount = (bet.spinsCount || 0) + 1;
        
        if (!MEM.statsByType[bet.type]) {
            MEM.statsByType[bet.type] = { amountBet:0, profit:0, currentLosingStreak:0, losingStreaks:[] };
        }
        
        MEM.statsByType[bet.type].amountBet = (MEM.statsByType[bet.type].amountBet || 0) + bet.betAmount;
        MEM.statsByType[bet.type].currentLosingStreak = (MEM.statsByType[bet.type].currentLosingStreak || 0) + 1;
        MEM.drawdownStats.currentLosingSpins = (MEM.drawdownStats.currentLosingSpins || 0) + 1;
        
        if (MEM.drawdownStats.currentLosingSpins > (MEM.drawdownStats.maxDrawdownSpins || 0)) {
            MEM.drawdownStats.maxDrawdownSpins = MEM.drawdownStats.currentLosingSpins;
        }
        
        if (bet.spinsCount >= (bet.maxSpins || 30)) {
            const totalLoss = (bet.betAmount || 0) * bet.spinsCount;
            MEM.totalLosses = (MEM.totalLosses || 0) + 1;
            MEM.totalProfit = (MEM.totalProfit || 0) - totalLoss;
            MEM.statsByType[bet.type].profit = (MEM.statsByType[bet.type].profit || 0) - totalLoss;
            MEM.balance = (MEM.balance || 100) - totalLoss;
            
            if (!MEM.statsByType[bet.type].losingStreaks) MEM.statsByType[bet.type].losingStreaks = [];
            MEM.statsByType[bet.type].losingStreaks.push(MEM.statsByType[bet.type].currentLosingStreak || 0);
            if (MEM.statsByType[bet.type].losingStreaks.length > 20) {
                MEM.statsByType[bet.type].losingStreaks.shift();
            }
            
            if (!MEM.detailedHistory) MEM.detailedHistory = [];
            MEM.detailedHistory.push({
                spin: MEM.totalSpins,
                type: 'LOSS_SERIES_END',
                group: bet.group,
                steps: bet.spinsCount,
                amount: totalLoss,
                profit: -totalLoss,
                totalProfit: MEM.totalProfit
            });
            
            if (MEM.config.diagnostics.logLevel !== 'minimal') {
                console.log(`  ❌ LOSS ${bet.group} после ${bet.spinsCount} спинов | -${totalLoss.toFixed(6)} | Баланс: ${(MEM.balance || 0).toFixed(2)}`);
            }
            
            MEM.activeBets.splice(betIndex, 1);
        } else {
            bet.progressionLevel++;
            
            const flatSteps = MEM.config.customGroupFlatSteps || 9;
            const progSteps = MEM.config.customGroupProgressionSteps || 5;
            const progThreshold = flatSteps + progSteps;
            
            if (!bet.recoveryMode && bet.progressionLevel > progThreshold) {
                bet.recoveryMode = true;
            }
            
            bet.betAmount = calculateCustomGroupBet(bet.progressionLevel, bet.recoveryMode || false);
            
            if (MEM.config.diagnostics.logLevel === 'detailed') {
                console.log(`  🔄 LOSS ${bet.group} | Шаг ${bet.progressionLevel}/${bet.maxSpins} | Нов.ставка: ${(bet.betAmount || 0).toFixed(6)}`);
            }
        }
        
        updateDrawdownTracking(-(bet.betAmount || 0));
    } catch (error) {
        console.error("Ошибка в processLoss:", error);
    }
}

// =========================================================
// ФУНКЦИИ ДИАГНОСТИКИ
// =========================================================

function runDiagnostics() {
    if (!MEM.config.diagnostics.enabled) return;
    
    const errors = [];
    const warnings = [];
    
    let negativeCount = 0;
    for (const group in MEM.currentMisses) {
        if (MEM.currentMisses[group] < 0) {
            negativeCount++;
            if (errors.length < 5) {
                errors.push(`Отрицательный возраст: ${group} = ${MEM.currentMisses[group]}`);
            }
        }
    }
    if (negativeCount > 0) {
        errors.push(`Всего ${negativeCount} групп с отрицательным возрастом`);
    }
    
    const ages = Object.values(MEM.currentMisses);
    const maxAge = ages.length > 0 ? Math.max(...ages) : 0;
    if (maxAge > 50) {
        warnings.push(`Аномально большой возраст: ${maxAge} (макс ожидаемый 45-48)`);
    }
    
    MEM.diagnostics.lastCheck = MEM.totalSpins;
    
    if (errors.length > 0) {
        MEM.diagnostics.checksFailed = (MEM.diagnostics.checksFailed || 0) + 1;
        MEM.diagnostics.errors = errors.slice(0, 10);
        MEM.diagnostics.errorHistory.push({
            spin: MEM.totalSpins,
            errors: [...errors],
            warnings: [...warnings],
            time: new Date().toLocaleTimeString()
        });
        if (MEM.diagnostics.errorHistory.length > 20) {
            MEM.diagnostics.errorHistory.shift();
        }
        
        MEM.diagnostics.consistencyScore = Math.max(0, (MEM.diagnostics.consistencyScore || 100) - errors.length * 5);
    } else {
        MEM.diagnostics.checksPassed = (MEM.diagnostics.checksPassed || 0) + 1;
        MEM.diagnostics.consistencyScore = Math.min(100, (MEM.diagnostics.consistencyScore || 100) + 1);
    }
    
    if (MEM.config.diagnostics.alertOnMismatch && (errors.length > 0 || warnings.length > 0)) {
        console.log("%c╔════════════════════════════════════════════════╗", "color: orange");
        console.log("%c║           ДИАГНОСТИКА ОБНАРУЖИЛА             ║", "color: orange; font-weight: bold");
        console.log("%c╚════════════════════════════════════════════════╝", "color: orange");
        
        if (errors.length > 0) {
            console.log("%c❌ ОШИБКИ:", "color: red; font-weight: bold");
            errors.slice(0, 3).forEach(e => console.log(`   ${e}`));
        }
        
        if (warnings.length > 0) {
            console.log("%c⚠️ ПРЕДУПРЕЖДЕНИЯ:", "color: yellow; font-weight: bold");
            warnings.slice(0, 3).forEach(w => console.log(`   ${w}`));
        }
    }
}

