        console.log(`\n🎲 СЛУЧАЙНЫЕ ГРУППЫ (${MEM.config.numberOfCustomGroups || 0} групп):`);
        const cg = MEM.statsByType.customGroup;
        console.log(`   Ставок: ${cg.bets || 0} | Выигрышей: ${cg.wins || 0} | Профит: %c${(cg.profit || 0) >= 0 ? '+' : ''}${(cg.profit || 0).toFixed(6)}`, 
                    `color: ${(cg.profit || 0) >= 0 ? 'green' : 'red'}`);
        
