// =========================================================
// ОСНОВНАЯ ЛОГИКА
// =========================================================
const lastRes = context.lastResult;

if (lastRes && lastRes.number !== undefined) {
    try {
        const realNum = lastRes.number;
        const color = getNumberColor(realNum);
        
        MEM.totalSpins = (MEM.totalSpins || 0) + 1;
        
        if (!MEM.lastNumbers) MEM.lastNumbers = [];
        MEM.lastNumbers.push(realNum);
        if (MEM.lastNumbers.length > 20) MEM.lastNumbers.shift();
        
        if (MEM.config.constantBets.enabled) {
            if (!MEM.constantBetsStats) {
                MEM.constantBetsStats = { spins:0, redHits:0, blackHits:0, zeroHits:0, totalSpent:0, totalWon:0, netProfit:0 };
            }
            
            MEM.constantBetsStats.spins = (MEM.constantBetsStats.spins || 0) + 1;
            MEM.constantBetsStats.totalSpent = (MEM.constantBetsStats.totalSpent || 0) + 
                (MEM.config.constantBets.redAmount || 0) + (MEM.config.constantBets.blackAmount || 0);
            
            if (color === 'red') {
                MEM.constantBetsStats.redHits = (MEM.constantBetsStats.redHits || 0) + 1;
                MEM.constantBetsStats.totalWon = (MEM.constantBetsStats.totalWon || 0) + 
                    ((MEM.config.constantBets.redAmount || 0) * 2);
            } else if (color === 'black') {
                MEM.constantBetsStats.blackHits = (MEM.constantBetsStats.blackHits || 0) + 1;
                MEM.constantBetsStats.totalWon = (MEM.constantBetsStats.totalWon || 0) + 
                    ((MEM.config.constantBets.blackAmount || 0) * 2);
            } else {
                MEM.constantBetsStats.zeroHits = (MEM.constantBetsStats.zeroHits || 0) + 1;
            }
            
            MEM.constantBetsStats.netProfit = (MEM.constantBetsStats.totalWon || 0) - (MEM.constantBetsStats.totalSpent || 0);
        }
        
        const hitGroups = updateMissCounters(realNum);
        
        if (MEM.activeBets && MEM.activeBets.length > 0) {
            for (let i = MEM.activeBets.length - 1; i >= 0; i--) {
                const bet = MEM.activeBets[i];
                if (!bet || !bet.group) continue;
                
                const groupData = MEM.allGroups[bet.group];
                if (!groupData) continue;
                
                const betNumbers = groupData.numbers;
                
                if (betNumbers.includes(realNum)) {
                    processWin(i, realNum);
                } else {
                    processLoss(i);
                }
            }
        }
        
        const spinsSinceLastBet = (MEM.totalSpins || 0) - (MEM.lastBetSpin || 0);
        if (spinsSinceLastBet >= (MEM.config.minSpinsBetweenBets || 8)) {
            const potentialBets = [];
            for (const groupName in MEM.allGroups) {
                const betInfo = checkGroupForBet(groupName);
                if (betInfo) {
                    const alreadyBetting = (MEM.activeBets || []).some(bet => bet && bet.group === groupName);
                    if (!alreadyBetting) {
                        potentialBets.push(betInfo);
                    }
                }
            }
            
            if (potentialBets.length > 0) {
                potentialBets.sort((a, b) => (b.currentMiss || 0) - (a.currentMiss || 0));
                const bestBet = potentialBets[0];
                
                let betAmount = calculateCustomGroupBet(0, false);
                
                if (!MEM.activeBets) MEM.activeBets = [];
                
                const newBet = {
                    group: bestBet.group,
                    type: bestBet.type,
                    betAmount: betAmount,
                    currentMiss: bestBet.currentMiss || 0,
                    progressionLevel: 0,
                    recoveryMode: false,
                    progressionData: { progressionLevel: 0 },
                    maxSpins: bestBet.maxSpins || 30,
                    startSpin: MEM.totalSpins
                };
                
                MEM.activeBets.push(newBet);
                MEM.totalBets = (MEM.totalBets || 0) + 1;
                
                if (!MEM.statsByType[bestBet.type]) {
                    MEM.statsByType[bestBet.type] = { bets:0 };
                }
                MEM.statsByType[bestBet.type].bets = (MEM.statsByType[bestBet.type].bets || 0) + 1;
                
                MEM.lastBetSpin = MEM.totalSpins;
                
                if (MEM.config.diagnostics.logLevel !== 'minimal') {
                    console.log(`\n🔔 НОВАЯ СТАВКА: ${bestBet.group} | ${bestBet.currentMiss || 0} misses | ${betAmount.toFixed(6)} USDT`);
                }
            }
        }
        
        if (MEM.config.diagnostics.enabled && MEM.totalSpins % MEM.config.diagnostics.checkInterval === 0) {
            runDiagnostics();
        }
        
        if (MEM.totalSpins % MEM.config.statsUpdateInterval === 0) {
            showVisualStats();
        }
    } catch (error) {
        console.error("Критическая ошибка в основном цикле:", error);
    }
}

// =========================================================
// ФОРМИРОВАНИЕ СТАВОК
// =========================================================
let payload = {
    colors: [],
    numbers: []
};

try {
    if (MEM.config.constantBets.enabled) {
        if (MEM.config.constantBets.redAmount > 0) {
            payload.colors.push({ value: 'colorRed', amount: MEM.config.constantBets.redAmount });
        }
        if (MEM.config.constantBets.blackAmount > 0) {
            payload.colors.push({ value: 'colorBlack', amount: MEM.config.constantBets.blackAmount });
        }
    }
    
    if (MEM.activeBets && MEM.activeBets.length > 0) {
        MEM.activeBets.forEach(bet => {
            if (!bet || !bet.group) return;
            
            const groupData = MEM.allGroups[bet.group];
            if (!groupData || !groupData.numbers) return;
            
            const numbers = groupData.numbers;
            const betAmount = bet.betAmount || 0;
            const betPerNumber = Number((betAmount / numbers.length).toFixed(8));
            
            if (betPerNumber > 0) {
                numbers.forEach(number => {
                    payload.numbers.push({
                        value: 'number' + number,
                        amount: betPerNumber
                    });
                });
            }
        });
    }
} catch (error) {
    console.error("Ошибка при формировании payload:", error);
}

