window.toggleDiagnostics = function(enabled) {
    MEM.config.diagnostics.enabled = enabled !== undefined ? enabled : !MEM.config.diagnostics.enabled;
    console.log(`[DIAGNOSTICS] ${MEM.config.diagnostics.enabled ? 'ENABLED' : 'DISABLED'}`);
};

window.showDiagnosticsReport = function() {
    console.log("%c📋 ПОЛНЫЙ ОТЧЕТ ДИАГНОСТИКИ", "color: cyan; font-size: 14px");
    console.log("==================================");
    console.log(`Статус: ${MEM.config.diagnostics.enabled ? 'АКТИВНА' : 'ОТКЛЮЧЕНА'}`);
    console.log(`Уровень логирования: ${MEM.config.diagnostics.logLevel}`);
    console.log(`Интервал проверки: ${MEM.config.diagnostics.checkInterval} спинов`);
    console.log(`Автоисправление: ${MEM.config.diagnostics.autoFix ? 'ДА' : 'НЕТ'}`);
    console.log(`\nСтатистика:`);
    console.log(`   Проверок пройдено: ${MEM.diagnostics.checksPassed || 0}`);
    console.log(`   Проверок с ошибками: ${MEM.diagnostics.checksFailed || 0}`);
    console.log(`   Текущая оценка: ${MEM.diagnostics.consistencyScore || 100}%`);
    
    if (MEM.diagnostics.errors && MEM.diagnostics.errors.length > 0) {
        console.log(`\nТекущие ошибки:`);
        MEM.diagnostics.errors.forEach(err => console.log(`   ❌ ${err}`));
    }
    
    if (MEM.diagnostics.errorHistory && MEM.diagnostics.errorHistory.length > 0) {
        console.log(`\nИстория ошибок (последние 5):`);
        MEM.diagnostics.errorHistory.slice(-5).forEach((entry, i) => {
            if (entry) {
                console.log(`   ${i+1}. Спин ${entry.spin || 0} (${entry.time || '??'}): ${(entry.errors || []).length} ошибок`);
            }
        });
    }
};

return {
    customPayload: payload
};
